from sympy import nextprime, isprime

def find_sequence(k):
    # Start checking from the smallest prime number
    p = 2
    while True:
        p = nextprime(p)
        # Try generating a sequence of distinct numbers modulo p
        for a1 in range(1, p):
            for a2 in range(1, p):
                if a2 == a1:
                    continue
                for a3 in range(1, p):
                    if a3 == a1 or a3 == a2:
                        continue
                    for a4 in range(1, p):
                        if a4 == a1 or a4 == a2 or a4 == a3:
                            continue
                        # Generate the rest of the sequence based on the condition
                        sequence = [a1, a2, a3, a4]
                        valid = True
                        for i in range(k):
                            next_a = ((i + 1) * pow(sequence[-1]*sequence[-2]*sequence[-3], -1, p)) % p
                            if next_a in sequence or next_a == 0:
                                valid = False
                                break
                            sequence.append(next_a)
                        if valid:
                            return p, tuple(sequence)

